import {PRODUCTS,validateRule,calculate} from './model.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=c=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format((c||0)/100);
async function api(path,data){const r=await fetch('/api/admin/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'Operation failed');return v;}
function field(f,value,attr='data-sample'){return `<label>${esc(f.label)}${f.type==='select'?`<select ${attr}="${f.key}">${f.options.map(o=>`<option value="${o.value}" ${o.value===value?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`:f.type==='checkbox'?`<input type="checkbox" ${attr}="${f.key}" ${value?'checked':''}>`:`<input type="number" ${attr}="${f.key}" min="${f.min}" max="${f.max}" step="${f.step}" value="${value}">`}</label>`;}
export async function mountRuleBuilder(root,message,path){root.innerHTML='<p>Loading pricing forms…</p>';let data;try{data=await api('rules');}catch(e){message(e.message,true);return;}let rules=data.rules,rule=structuredClone(rules.find(r=>r.path===path)||rules[0]),sample={},revision=rule.revision;
if(path&&!rules.some(r=>r.path===path)){rule={id:'custom-'+crypto.randomUUID().slice(0,8),label:'Custom price estimator',path,fields:[{key:'quantity',label:'Quantity',type:'number',default:1,min:1,max:10000,step:1}],constants:{unitPrice:10},formula:'quantity * unitPrice',deposit:{type:'percent',value:50},discount:{type:'percent',value:0},taxPercent:13,revision:0};revision=0;}
const $=s=>root.querySelector(s);
function render(){sample={};root.innerHTML=`<div class="toolbar"><label>Pricing form<select data-rule-picker>${rules.map(r=>`<option value="${r.id}" ${r.id===rule.id?'selected':''}>${esc(r.label)}</option>`).join('')}</select></label><button data-new-rule>New pricing form</button><button class="primary" data-save-rule>Save & publish form</button><a class="button" href="${esc(rule.path)}/" target="_blank">View page</a></div><div class="rule-builder-grid"><div><div class="panel"><h2>Form settings</h2><div class="form-grid"><label class="check"><input data-quote-only type="checkbox" ${rule.priceOnRequest?'checked':''}>Price on request until configured</label><label>Estimate note<textarea data-rule-prop="priceNote">${esc(rule.priceNote)}</textarea></label><label>Name<input data-rule-prop="label" value="${esc(rule.label)}"></label><label>Page path<input data-rule-prop="path" value="${esc(rule.path)}" placeholder="/satin/vehicle-wraps/estimator/transit-van"></label></div><p class="muted">This replaces the calculator on this page. Changes publish when you save. Use field keys and constants in the formula.</p></div><div class="panel"><div class="toolbar"><h2>Fields</h2><button data-add-field>Add field</button></div><div data-field-editor></div></div><div class="panel"><div class="toolbar"><h2>Constants</h2><button data-add-constant>Add constant</button></div><div data-constants></div></div><div class="panel"><h2>Formula</h2><textarea data-formula rows="5" spellcheck="false">${esc(rule.formula)}</textarea><div class="toolbar" data-insert-fields></div><p class="muted">Supports + − * / %, comparisons, parentheses, and min(), max(), round(), ceil(), floor(), abs(), if(condition, yes, no). Example: quantity * unitPrice + setupFee.</p><div class="form-grid"><label>Deposit type<select data-payment-setting="deposit.type"><option value="percent" ${rule.deposit.type==='percent'?'selected':''}>Percentage of total</option><option value="fixed" ${rule.deposit.type==='fixed'?'selected':''}>Fixed CAD</option></select></label><label>Deposit value<input type="number" data-payment-setting="deposit.value" value="${rule.deposit.value}" min="0"></label><label>Automatic discount<select data-payment-setting="discount.type"><option value="percent" ${rule.discount.type==='percent'?'selected':''}>Percentage</option><option value="fixed" ${rule.discount.type==='fixed'?'selected':''}>Fixed CAD</option></select></label><label>Discount value<input type="number" data-payment-setting="discount.value" value="${rule.discount.value}" min="0"></label><label>Tax %<input data-rule-prop="taxPercent" type="number" min="0" max="30" step=".01" value="${rule.taxPercent}"></label></div><p class="muted">Deposit is based on the discounted total including tax. The largest eligible automatic or coupon discount applies; discounts do not stack. Payment collection is not connected.</p></div></div><aside class="panel rule-preview"><h2>Test this form</h2><div class="field-list" data-test-fields></div><div class="studio-price" data-test-result></div><p role="status" class="status-error" data-formula-error></p></aside></div>`;drawFields();drawConstants();drawSample();bind();}
function drawFields(){$('[data-field-editor]').innerHTML=rule.fields.map((f,i)=>`<section class="edit-row"><div class="toolbar"><b>Field ${i+1}</b><button data-field-up="${i}" ${i?'':'disabled'}>Up</button><button data-field-down="${i}" ${i<rule.fields.length-1?'':'disabled'}>Down</button><button data-remove-field="${i}">Remove</button></div><div class="form-grid"><label>Label<input data-field-index="${i}" data-prop="label" value="${esc(f.label)}"></label>${['fa','fr','es'].map(lang=>`<label>Label (${lang})<input data-field-index="${i}" data-prop="label_${lang}" value="${esc(f.translations?.[lang]||'')}"></label>`).join('')}<label>Key used in formula<input data-field-index="${i}" data-prop="key" value="${f.key}"></label><label>Type<select data-field-index="${i}" data-prop="type">${['number','select','checkbox'].map(t=>`<option ${f.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Default value<input data-field-index="${i}" data-prop="default" type="number" step="any" value="${f.default}"></label>${f.type==='number'?['min','max','step'].map(k=>`<label>${k}<input data-field-index="${i}" data-prop="${k}" type="number" step="any" value="${f[k]}"></label>`).join(''):''}</div>${f.type==='select'?`<p class="muted">Option label and its numerical value in the formula.</p>${f.options.map((o,n)=>`<div class="rule-option"><input aria-label="Option label" data-option-field="${i}" data-option-index="${n}" data-option-prop="label" value="${esc(o.label)}"><input aria-label="Option value" data-option-field="${i}" data-option-index="${n}" data-option-prop="value" type="number" step="any" value="${o.value}"><button data-remove-option="${i}:${n}">×</button></div>`).join('')}<button data-add-option="${i}">Add option</button>`:''}</section>`).join('');$('[data-insert-fields]').innerHTML=rule.fields.map(f=>`<button data-insert="${esc(f.key)}">${esc(f.key)}</button>`).join('');}
function drawConstants(){$('[data-constants]').innerHTML=Object.entries(rule.constants).map(([k,v],i)=>`<div class="rule-option"><input aria-label="Constant key" data-constant="${i}" data-prop="key" value="${k}"><input aria-label="Constant value" data-constant="${i}" data-prop="value" type="number" step="any" value="${v}"><button data-remove-constant="${i}">×</button></div>`).join('')||'<p class="muted">No constants. You can use numbers directly in the formula.</p>';}
function drawSample(){for(const f of rule.fields)if(sample[f.key]===undefined)sample[f.key]=f.default;$('[data-test-fields]').innerHTML=rule.fields.map(f=>field(f,sample[f.key])).join('');preview();}
function preview(){try{validateRule(rule);const p=calculate(rule,sample);$('[data-test-result]').innerHTML=`<div><span>Subtotal</span><b>${money(p.subtotal)}</b></div><div><span>Discount</span><span>${money(p.discount)}</span></div><div><span>Tax</span><span>${money(p.tax)}</span></div><div class="total"><span>Total</span><b>${money(p.total)}</b></div><div><span>Deposit</span><span>${money(p.deposit)}</span></div><div><span>Balance</span><span>${money(p.balance)}</span></div>`;$('[data-formula-error]').textContent='';}catch(e){$('[data-formula-error]').textContent=e.message;$('[data-test-result]').innerHTML='';}}
function bind(){root.oninput=e=>{const t=e.target;if(t.hasAttribute('data-quote-only'))rule.priceOnRequest=t.checked;if(t.dataset.ruleProp)rule[t.dataset.ruleProp]=t.type==='number'?Number(t.value):t.value;if(t.hasAttribute('data-formula'))rule.formula=t.value;if(t.dataset.fieldIndex!==undefined){const f=rule.fields[Number(t.dataset.fieldIndex)];if(t.dataset.prop.startsWith('label_')){f.translations||={};f.translations[t.dataset.prop.slice(6)]=t.value;}else f[t.dataset.prop]=t.type==='number'?Number(t.value):t.value;if(t.dataset.prop==='type'){if(t.value==='select'){f.options=[{label:'Option 1',value:1},{label:'Option 2',value:2}];f.default=1;}if(t.value==='number'){f.min=0;f.max=100000;f.step=1;f.default=1;}if(t.value==='checkbox')f.default=0;drawFields();drawSample();return;}if(t.dataset.prop==='key'||t.dataset.prop==='default'){sample={};drawSample();return;}}if(t.dataset.optionField!==undefined){const o=rule.fields[Number(t.dataset.optionField)].options[Number(t.dataset.optionIndex)];o[t.dataset.optionProp]=t.type==='number'?Number(t.value):t.value;}if(t.dataset.constant!==undefined){const entries=Object.entries(rule.constants),i=Number(t.dataset.constant);entries[i][t.dataset.prop==='key'?0:1]=t.type==='number'?Number(t.value):t.value;rule.constants=Object.fromEntries(entries);}if(t.dataset.paymentSetting){const [section,k]=t.dataset.paymentSetting.split('.');rule[section][k]=t.type==='number'?Number(t.value):t.value;}if(t.dataset.sample)sample[t.dataset.sample]=t.type==='checkbox'?+t.checked:Number(t.value);preview();};root.onchange=e=>{if(e.target.hasAttribute('data-rule-picker')){rule=structuredClone(rules.find(r=>r.id===e.target.value));revision=rule.revision;render();}};
root.onclick=async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-save-rule')){validateRule(rule);b.disabled=true;const d=await api('rule',{rule,expectedRevision:revision});revision=d.revision;rule.revision=revision;const i=rules.findIndex(r=>r.id===rule.id);if(i>=0)rules[i]=structuredClone(rule);else rules.push(structuredClone(rule));message('Pricing form, formula, deposit and discount published.');b.disabled=false;}if(b.hasAttribute('data-new-rule')){rule={id:'custom-'+crypto.randomUUID().slice(0,8),label:'New price estimator',path:path||'/satin/wallpaper',fields:[{key:'quantity',label:'Quantity',type:'number',default:1,min:1,max:10000,step:1}],constants:{unitPrice:10},formula:'quantity * unitPrice',deposit:{type:'percent',value:50},discount:{type:'percent',value:0},taxPercent:13,revision:0};revision=0;render();}if(b.hasAttribute('data-add-field')){rule.fields.push({key:'field_'+(rule.fields.length+1),label:'New field',type:'number',default:1,min:0,max:10000,step:1});drawFields();drawSample();}if(b.dataset.removeField!==undefined){rule.fields.splice(Number(b.dataset.removeField),1);drawFields();drawSample();}if(b.dataset.fieldUp!==undefined){const i=Number(b.dataset.fieldUp);[rule.fields[i-1],rule.fields[i]]=[rule.fields[i],rule.fields[i-1]];drawFields();drawSample();}if(b.dataset.fieldDown!==undefined){const i=Number(b.dataset.fieldDown);[rule.fields[i+1],rule.fields[i]]=[rule.fields[i],rule.fields[i+1]];drawFields();drawSample();}if(b.dataset.addOption!==undefined){rule.fields[Number(b.dataset.addOption)].options.push({label:'New option',value:0});drawFields();drawSample();}if(b.dataset.removeOption){const [i,n]=b.dataset.removeOption.split(':').map(Number);rule.fields[i].options.splice(n,1);drawFields();drawSample();}if(b.hasAttribute('data-add-constant')){rule.constants['constant'+(Object.keys(rule.constants).length+1)]=0;drawConstants();preview();}if(b.dataset.removeConstant!==undefined){delete rule.constants[Object.keys(rule.constants)[Number(b.dataset.removeConstant)]];drawConstants();preview();}if(b.dataset.insert){const t=$('[data-formula]'),pos=t.selectionStart;t.setRangeText(b.dataset.insert,pos,t.selectionEnd,'end');rule.formula=t.value;t.focus();preview();}}catch(err){message(err.message,true);b.disabled=false;}};
}
render();}
export async function mountCoupons(root,message){let coupons;try{coupons=(await api('coupons')).coupons;}catch(e){message(e.message,true);return;}function draw(){root.innerHTML=`<div class="toolbar"><button data-add-code>Add discount code</button><button class="primary" data-save-codes>Save codes</button></div><div class="panel"><h2>Discount codes</h2><p class="muted">Percentage or fixed CAD discount. The larger eligible coupon or automatic discount applies. Saving does not send messages or take payments.</p><div data-codes>${coupons.map((c,i)=>`<div class="edit-row"><div class="form-grid"><label>Code<input data-code="${i}" data-prop="code" value="${c.code}"></label><label>Type<select data-code="${i}" data-prop="type"><option value="percent" ${c.type==='percent'?'selected':''}>Percentage</option><option value="fixed" ${c.type==='fixed'?'selected':''}>Fixed CAD</option></select></label><label>Value<input data-code="${i}" data-prop="value" type="number" value="${c.value}"></label><label>Minimum subtotal CAD<input data-code="${i}" data-prop="minimum" type="number" value="${c.minimum}"></label><label>Expiry date · optional<input data-code="${i}" data-prop="expires" type="date" value="${c.expires}"></label><label>Applicable rule IDs · optional, comma separated<input data-code="${i}" data-prop="rules" value="${esc(c.rules.join(', '))}"></label><label class="check"><input type="checkbox" data-code="${i}" data-prop="active" ${c.active?'checked':''}>Active</label></div><button data-remove-code="${i}">Remove code</button></div>`).join('')||'<p class="empty">No discount codes yet.</p>'}</div></div>`;root.oninput=e=>{const t=e.target;if(t.dataset.code!==undefined)coupons[Number(t.dataset.code)][t.dataset.prop]=t.type==='checkbox'?t.checked:t.type==='number'?Number(t.value):t.dataset.prop==='rules'?t.value.split(',').map(v=>v.trim()).filter(Boolean):t.dataset.prop==='code'?t.value.toUpperCase():t.value;};root.onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-add-code')){coupons.push({code:'NEW'+(coupons.length+1),type:'percent',value:10,minimum:0,expires:'',active:true,rules:[]});draw();}if(b.dataset.removeCode!==undefined){coupons.splice(Number(b.dataset.removeCode),1);draw();}if(b.hasAttribute('data-save-codes')){b.disabled=true;try{await api('coupons',{coupons});message('Discount codes saved.');}catch(err){message(err.message,true);}finally{b.disabled=false;}}};}draw();}
export async function mountProcess(root,message){let steps;try{steps=(await api('process')).steps;}catch(e){message(e.message,true);return;}function draw(){root.innerHTML=`<div class="toolbar"><button data-add-step>Add process step</button><button class="primary" data-save-process>Save process</button></div><div class="panel"><h2>Order process</h2><p class="muted">These steps are available on submitted design orders. Keep the Submitted key. Changing a step does not send customer notifications.</p>${steps.map((s,i)=>`<div class="rule-option"><input aria-label="Process key" data-step="${i}" data-prop="key" value="${s.key}" ${s.key==='submitted'?'readonly':''}><input aria-label="Process label" data-step="${i}" data-prop="label" value="${esc(s.label)}"><button data-step-up="${i}" ${i?'':'disabled'}>Up</button><button data-step-remove="${i}" ${s.key==='submitted'?'disabled':''}>Remove</button></div>`).join('')}</div>`;root.oninput=e=>{const t=e.target;if(t.dataset.step!==undefined)steps[Number(t.dataset.step)][t.dataset.prop]=t.value;};root.onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-add-step')){steps.push({key:'step_'+(steps.length+1),label:'New step'});draw();}if(b.dataset.stepUp!==undefined){const i=Number(b.dataset.stepUp);[steps[i-1],steps[i]]=[steps[i],steps[i-1]];draw();}if(b.dataset.stepRemove!==undefined){steps.splice(Number(b.dataset.stepRemove),1);draw();}if(b.hasAttribute('data-save-process')){b.disabled=true;try{await api('process',{steps});message('Order process saved.');}catch(err){message(err.message,true);}finally{b.disabled=false;}}};}draw();}
export async function mountDesignOrders(root,message){root.innerHTML='<p>Loading saved artwork and orders…</p>';let data;try{data=await api('design-orders');}catch(e){message(e.message,true);return;}const orders=new Map(data.orders.map(o=>[o.id,o]));const items=data.items.filter(i=>i.status!=='removed');root.innerHTML=`<div class="panel"><h2>Design orders & carts</h2><p class="muted">Items appear here as soon as a customer adds an approved design to their cart. Unsubmitted carts have no confirmed customer details. SVG files contain the approved artwork with bleed; PNGs are customer previews. Check print readiness before production.</p><div class="toolbar"><label>Filter<select data-design-filter><option value="all">All designs</option><option value="submitted">Submitted orders</option><option value="in_cart">Unsubmitted carts</option></select></label><button data-refresh-designs>Refresh designs</button></div><div data-design-list></div></div>`;const $=s=>root.querySelector(s);function draw(filter='all'){$('[data-design-list]').innerHTML=items.filter(i=>filter==='all'||i.status===filter).map(i=>{const o=orders.get(i.order_id),d=i.design,p=PRODUCTS.find(p=>p.id===d.productId),files=d.generated||[];return `<article class="design-order"><div class="design-order-visual"><img src="/api/studio/file?id=${files.find(f=>f.role==='mockup')?.id}&inline=1" alt="${esc(p.name)} mockup"><img src="/api/studio/file?id=${files.find(f=>f.role==='preview')?.id}&inline=1" alt="Flat artwork preview"></div><div><span class="pill">${o?esc(o.status):'Unsubmitted cart'}</span><h3>${esc(p.name)} · ${d.options.quantity} pcs</h3><p>${d.dimensions.width} × ${d.dimensions.height} in · ${esc(d.options.orientation)} ${d.options.rounded?'· Rounded corners':''} ${esc(d.options.fold||'')}</p><p>${(d.printSpecifications||[]).map(f=>`${esc(f.label)}: ${esc(f.selection)}`).join(' · ')} · ${d.options.sideCount} print side(s)</p><p><b>${money(i.price.total)}</b> · Proposed deposit ${money(i.price.deposit)} · No payment collected</p>${o?`<p><b>${esc(o.customer.name)}</b><br>${esc(o.customer.email)}<br>${esc(o.customer.phone)}</p><p>Order SG-${esc(o.id.slice(0,8).toUpperCase())}</p><p class="details">${esc(o.customer.notes)}</p><label>Process<select data-order-status="${o.id}">${data.steps.map(s=>`<option value="${s.key}" ${o.status===s.key?'selected':''}>${esc(s.label)}</option>`).join('')}</select></label><label>Internal notes<textarea data-order-notes="${o.id}">${esc(o.admin_notes)}</textarea></label><button data-save-order="${o.id}">Save order status & notes</button>`:'<p class="muted">Customer has not submitted contact details yet.</p>'}<p class="details">${esc(d.notes)}</p><h3>Approved files</h3><div class="file-downloads">${files.map(f=>`<a href="/api/studio/file?id=${f.id}" download>${esc(f.name)}</a>`).join('')}</div><h3>Original uploads</h3><div class="file-downloads">${d.originals.map(f=>`<a href="/api/studio/file?id=${f.id}" download>${esc(f.name)} · ${(f.size/1024/1024).toFixed(1)} MB</a>`).join('')||'<span class="muted">No uploaded files.</span>'}</div></div></article>`;}).join('')||'<p class="empty">No matching designs yet.</p>';};draw();$('[data-design-filter]').onchange=e=>draw(e.target.value);$('[data-refresh-designs]').onclick=()=>mountDesignOrders(root,message);root.onclick=async e=>{const b=e.target.closest('[data-save-order]');if(!b)return;b.disabled=true;try{const id=b.dataset.saveOrder,status=b.closest('.design-order').querySelector(`[data-order-status="${id}"]`).value,notes=b.closest('.design-order').querySelector(`[data-order-notes="${id}"]`).value;await api('design-order',{id,status,notes});orders.get(id).status=status;orders.get(id).admin_notes=notes;message('Order status and notes saved.');}catch(err){message(err.message,true);}finally{b.disabled=false;}};}
